insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_em', 8, '8.2', array['8.2']::text[], 'vocabulary', 'Induced charge separation', 'Induced charge separation occurs when the electrostatic force between two systems alters the distribution of charges within them, polarizing one or both, and it can occur in neutral systems.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-em-reference-u8-u10-2026-10-10; candidate=ap_physics_c_em-u8-r1-012; ced=8.2.A.1.ii–iii "Induced charge separation"')
