values ('ap_physics_c_em', 8, '8.3', array['8.3']::text[], 'convention', 'Field outside a spherically symmetric charge', 'The electric field outside an isolated sphere with spherically symmetric charge distribution is the same as that of a point charge with the sphere''s net charge located at its center.', '[]'::jsonb, NULL, 'This applies outside the sphere; it does not describe the field inside the sphere.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-em-reference-u8-u10-2026-10-10; candidate=ap_physics_c_em-u8-r2-007; ced=8.3.B.1.ii: "the same as the electric field due to a point charge with the same net charge as the sphere located at the center of the sphere"')
